import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gelu_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor gelu_forward(torch::Tensor x);
"""

gelu_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float gelu_scalar(float v) {
    const float k0 = 0.79788456080286535588f; // sqrt(2/pi)
    const float k1 = 0.044715f;
    float v3 = v * v * v;
    float inner = k0 * (v + k1 * v3);
    float t = tanhf(inner);
    return 0.5f * v * (1.0f + t);
}

__global__ void gelu_cute_kernel(const float4* __restrict__ X4,
                                 float4* __restrict__ Y4,
                                 const float* __restrict__ X1,
                                 float* __restrict__ Y1,
                                 int nvec,
                                 int rem,
                                 long long total)
{
    constexpr int Threads = 256;
    constexpr int Items   = 4;                    // float4 per thread per tile
    constexpr int Tile    = Threads * Items;      // float4 per CTA tile

    Tensor mX = make_tensor(make_gmem_ptr(X4), make_shape(nvec));
    Tensor mY = make_tensor(make_gmem_ptr(Y4), make_shape(nvec));

    const int tid = threadIdx.x;
    const int grid_stride = gridDim.x * Tile;

    for (int base = blockIdx.x * Tile; base < nvec; base += grid_stride) {
        #pragma unroll
        for (int j = 0; j < Items; ++j) {
            int i = base + tid + j * Threads;
            if (i < nvec) {
                float4 v = mX(i);
                v.x = gelu_scalar(v.x);
                v.y = gelu_scalar(v.y);
                v.z = gelu_scalar(v.z);
                v.w = gelu_scalar(v.w);
                mY(i) = v;
            }
        }
    }

    // Handle scalar tail inside the same kernel.
    if (rem > 0 && blockIdx.x == 0 && tid < rem) {
        long long idx = (long long)nvec * 4 + tid;
        if (idx < total) {
            Tensor sX = make_tensor(make_gmem_ptr(X1), make_shape(total));
            Tensor sY = make_tensor(make_gmem_ptr(Y1), make_shape(total));
            sY(idx) = gelu_scalar(sX(idx));
        }
    }
}

torch::Tensor gelu_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

    auto xc = x.contiguous();
    auto y = torch::empty_like(xc);

    const long long total = xc.numel();
    if (total == 0) {
        return y;
    }

    const int nvec = (int)(total / 4);
    const int rem  = (int)(total % 4);

    constexpr int Threads = 256;
    constexpr int Items   = 4;
    constexpr int Tile    = Threads * Items;

    int needed = (nvec + Tile - 1) / Tile;
    if (needed <= 0) needed = 1;
    int blocks = needed < 8192 ? needed : 8192;

    const float* xptr = xc.data_ptr<float>();
    float* yptr = y.data_ptr<float>();

    const float4* x4 = reinterpret_cast<const float4*>(xptr);
    float4* y4 = reinterpret_cast<float4*>(yptr);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    gelu_cute_kernel<<<blocks, Threads, 0, stream>>>(x4, y4, xptr, yptr, nvec, rem, total);

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "gelu_cute_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

gelu_ext = load_inline(
    name="cute_gelu_inline",
    cpp_sources=gelu_cpp_decl,
    cuda_sources=gelu_cuda_src,
    functions=["gelu_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = gelu_ext

    def forward(self, x):
        return self._ext.gelu_forward(x)

